修復目前原Plan的search Stage，保留原Module/session/slug與run({page}) API、前序login固定版本及後序args/bindings。下面是PM人工提供、用同部署Worker映像與同商店程式的隔離複本完成真verifyDraft的完整參考候選，不是retry5原稿；正常登入搜尋通過，未登入與錯價負向斷言都會失敗。
請直接逐字採用下方script/harness/metadata，不探索、不重讀draft/reference、不重新設計，不更動內容或刪除/弱化斷言。依序呼叫stage_module_candidate_part(part=script,stagingRevision=0)、stage_module_candidate_part(part=harness,stagingRevision=1)，再commit_module_candidate(stagingRevision=2,metadata=下方metadata)執行真自試。使用實際工具回覆revision，不猜成功。commit自試通過後只回短final；本Plan由Server自動排正式validation，不另耗模型回合request_module_validation。不通過要據實回報，不把工具succeeded當自試通過。
作用域仍僅http://host.docker.internal:19387；真平台loginAs由broker提供帳密，不讀取/索取/硬編帳密。不browser探索，不任意Node網路，不外網，不真付款、不假登入、不舊訂單。productId必從當次DOM讀取，price從當次頁面解析後斷言120，不把預期值當回傳資料。維持原8模型/12工具/180秒/16384與模型，不擴大budget或自行修改skills。不summary/publish。
完整候選（JSON資料；逐字使用字串值）：
{
  "script": "import { expect, type Page } from '@playwright/test';

export async function run({ page }: { page: Page }): Promise<{ productId: string; price: number }> {
  await expect(page.getByTestId('account-state')).toHaveText('Authenticated synthetic customer');
  await page.locator('input[name="q"]').fill('Whippet');
  await page.getByRole('button', { name: 'Search', exact: true }).click();
  const product = page.getByTestId('product');
  await expect(product).toHaveCount(1);
  await expect(product.locator('h2')).toContainText('Whippet');
  const productId = await product.getAttribute('data-product-id');
  expect(productId).toBeTruthy();
  const price = Number(await product.getByTestId('unit-price').innerText());
  expect(Number.isFinite(price)).toBe(true);
  expect(price).toBe(120);
  return { productId: productId!, price };
}
",
  "harness": "import { test, expect } from '@playwright/test';
import { loginAs } from 'whippet/login';
import { run } from '@lib/shop-t4r-20261114-search';

test('search returns current productId and price after real role login', async ({ page }) => {
  await page.goto('http://host.docker.internal:19387/login');
  await loginAs(page, '7da20730-874d-41ff-aea0-7a5650f37c12',
    'input[name=username]', 'input[name=password]', 'button[type=submit]');
  await expect(page).toHaveURL('http://host.docker.internal:19387/products');
  await expect(page.getByTestId('account-state')).toHaveText('Authenticated synthetic customer');
  const result = await run({ page });
  expect(result.productId).toBeTruthy();
  expect(result.price).toBe(120);
  const product = page.getByTestId('product');
  await expect(product.locator('h2')).toContainText('Whippet');
  await expect(product).toHaveAttribute('data-product-id', result.productId);
  await expect(product.getByTestId('unit-price')).toHaveText('120');
});
",
  "metadata": {
    "slug": "shop-t4r-20261114-search",
    "moduleKind": "step",
    "exportName": "run",
    "signature": "run({page}): Promise<{productId:string,price:number}>",
    "inputs": "page: same authenticated Playwright Page from login Stage",
    "returns": "Current DOM productId and numeric price",
    "preconditions": "Authenticated synthetic customer on /products within confirmed shop origin",
    "postconditions": "Search Whippet; one matching product; nonempty dynamic productId; finite price equals 120"
  }
}
